mapper.select:
select r.*, u1.username as patientName, u2.username as doctorName
from registration r
left join patient p on r.patient_id = p.patient_id
left join user u1 on p.user_id = u1.user_id
left join doctor d on r.doctor_id = d.doctor_id
left join user u2 on d.user_id = u2.user_id


        r.status = #{status}


        and r.doctor_id = #{doctorId}


        and r.patient_id = #{patientId}


order by field(r.status, 'waiting', 'in_progress', 'completed', 'cancelled'), r.queue_number
